use std::vec;
use std::collections::HashSet;
use actix_web::{get, http, web, App, HttpServer, HttpRequest ,HttpResponse,  Responder};
use serde::{Deserialize, Serialize};
use std::error::Error;
use reqwest::{self, Client};
use regex::Regex;
use lazy_static::lazy_static;
use actix_cors::Cors;

use base64::engine::general_purpose::STANDARD as BASE64;
use base64::Engine;

const BASE_URL : &str = "https://en.wikipedia.org/w/api.php" ;
const MY_USER_AGENT: &str = "BearFetcher/1.0 (contact@example.com)";
const PLACEHOLDER_IMAGE: &str = "";  // replace with your placeholder

#[derive(Debug, Serialize, Deserialize, Clone)]
struct Bear {
    name: String,
    bionominal: String,
    image_base_64: String,
    range: String,
}

#[derive(Debug, Clone)]
pub struct BearInternal {
    pub name: String,
    pub binomial: String,
    pub image_file: String,
    pub range: String,
}

type BearResult<T> = Result<T, Box<dyn Error>>;

#[get("/more-bears-rust")]
async fn more_bears() -> impl Responder {
    let bears_result: BearResult<Vec<Bear>> = fetch_bears_async().await;

    match bears_result {
        Ok(bears_list) => {
            HttpResponse::Ok().json(bears_list)
        },
        Err(e) => {
            eprintln!("Error fetching bears: {}", e);
            HttpResponse::InternalServerError().body(format!("Failed to fetch bear data: {}", e))
        }
    }
}

async fn fetch_bears_async() -> BearResult<Vec<Bear>> {
    let params = [
        ("action", "parse"), 
        ("page", "List_of_ursids"), 
        ("prop", "wikitext"), 
        ("section", "3"), 
        ("format", "json"),
        ("origin", "*"),
    ];

    let client = Client::builder()
        .user_agent(MY_USER_AGENT)
        .build()?;

    let response = client
        .get(BASE_URL)
        .query(&params)
        .send()
        .await?;

    #[derive(Deserialize)]
    struct WikiResponse {
        parse: Parse,
    }
    #[derive(Deserialize)]
    struct Parse {
        wikitext: Wikitext,
    }
    #[derive(Deserialize)]
    struct Wikitext {
        #[serde(rename = "*")]
        text: String,
    }

    let wiki: WikiResponse = response.json().await?;

    let raw_wikitext = wiki.parse.wikitext.text;

    let bears_int = extract_bears_from_wikitext(&raw_wikitext);
    let cleaned =remove_duplicates(bears_int);
    
    fetch_images_for_bears(cleaned).await

}


fn extract_bears_from_wikitext(wikitext: &str) -> Vec<BearInternal> {
    let mut bears = Vec::new();

    lazy_static! {
        static ref NAME_RE: Regex = Regex::new(r"\|name=\[\[(.*?)\]\]").unwrap();
        static ref BINOMIAL_RE: Regex = Regex::new(r"\|binomial=(.*?)\n").unwrap();
        static ref IMAGE_RE: Regex = Regex::new(r"\|image=(.*?)\n").unwrap();
        static ref RANGE_RE: Regex = Regex::new(r"\|range=([^\|]+)").unwrap();
    }

    for section in wikitext.split("{{Species table/end}}") {
        let rows: Vec<&str> = section.split("{{Species table/row").collect();
        if rows.len() <= 1 {
            continue;
        }

        for row in &rows[1..] {
            let name_caps = NAME_RE.captures(row);
            let binom_caps = BINOMIAL_RE.captures(row);

            if name_caps.is_none() || binom_caps.is_none() {
                continue;
            }

            let name = name_caps.unwrap()[1].trim().to_string();
            let binomial = binom_caps.unwrap()[1].trim().to_string();

            // Image
            let image_file = IMAGE_RE
                .captures(row)
                .map(|c| {
                    let raw = c[1].trim();
                    let first = raw.split('|').next().unwrap_or("").trim();
                    first.trim_start_matches("File:").to_string()
                })
                .unwrap_or_else(|| "".to_string());

            // Range
            let range = RANGE_RE
                .captures(row)
                .map(|c| c[1].trim().to_string())
                .unwrap_or_else(|| "Unknown".to_string());

            bears.push(BearInternal {
                name,
                binomial,
                image_file,
                range,
            });
        }
    }

    bears
}

#[derive(Debug, Deserialize)]
struct QueryResponse {
    query: Query,
}

#[derive(Debug, Deserialize)]
struct Query {
    pages: std::collections::HashMap<String, Page>,
}

#[derive(Debug, Deserialize)]
struct Page {
    #[serde(default)]
    imageinfo: Vec<ImageInfo>,
}

#[derive(Debug, Deserialize)]
struct ImageInfo {
    url: String,
}


async fn fetch_image(file_name: &str) -> Result<String, Box<dyn std::error::Error>> {
    if file_name.is_empty() {
        return Ok(PLACEHOLDER_IMAGE.to_string());
    }

    let params = [
        ("action", "query"),
        ("titles", &format!("File:{}", file_name)),
        ("prop", "imageinfo"),
        ("iiprop", "url"),
        ("format", "json"),
        ("origin", "*"),
    ];

    let client = Client::builder()
        .user_agent(MY_USER_AGENT)
        .build()?;

    // Call Wikipedia API for metadata
    let response = client
        .get(BASE_URL)
        .query(&params)
        .send()
        .await?;

    let api_json: QueryResponse = response.json().await?;

    // Extract image URL from first page that contains one
    let image_url = api_json
        .query
        .pages
        .values()
        .find_map(|page| {
            page.imageinfo.get(0).map(|info| info.url.clone())
        });

    let Some(url) = image_url else {
        return Ok(PLACEHOLDER_IMAGE.to_string());
    };

    // Download actual image

    let img_resp = client.get(&url).send().await?;

    if !img_resp.status().is_success() {
        return Ok(PLACEHOLDER_IMAGE.to_string());
    }

    let bytes = img_resp.bytes().await?;

    // Encode as Base64
    let encoded = BASE64.encode(&bytes);

    Ok(encoded)
}


fn remove_duplicates(bears: Vec<BearInternal>) -> Vec<BearInternal> {
    let mut seen = HashSet::new();
    let mut out = Vec::new();

    for b in bears {
        if seen.insert(b.binomial.clone()) {
            // insert returns true if it was not already in the set
            out.push(b);
        }
    }

    out
}

pub async fn fetch_images_for_bears(
    bears: Vec<BearInternal>
) -> BearResult<Vec<Bear>> { // Adjusted to use BearResult
    let mut out = Vec::with_capacity(bears.len());

    for b in bears {
        // Fetch image, on error or failure, use the placeholder.
        let image_base64 = match fetch_image(&b.image_file).await {
            Ok(img) => img,
            Err(e) => {
                eprintln!("Error fetching image for {}: {}", b.name, e);
                PLACEHOLDER_IMAGE.to_string()
            },
        };

        out.push(Bear {
            name: b.name,
            bionominal: b.binomial,
            image_base_64: image_base64,
            range: b.range,
        });
    }

    Ok(out)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    println!("🐻 Server running at http://0.0.0.0:3000");
    HttpServer::new(|| {
    let cors = Cors::default()
            .allowed_origin("http://0.0.0.0:8080")
            .allowed_methods(vec!["GET"])
            .allowed_headers(vec![http::header::AUTHORIZATION, http::header::ACCEPT])
            .allowed_header(http::header::CONTENT_TYPE)
            .max_age(3600);

        App::new()
            .wrap(cors)
            .service(more_bears)
    })
    .bind(("0.0.0.0", 3000))?
    .run()
    .await;

    Ok(())
}

